/*
 * A050821  Even numbers in the sequence generated by a(n)=|a(n-1)+2a(n-2)-n|
 *          where a(0)=a(1)=1.
 * https://oeis.org/A050821
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 75, u16 n <= 75, u32 n <= 75, u64 n <= 75, u128 n <= 75,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Even numbers of the sequence defined by
 * a(0) = a(1) = 1,
 * a(n) = |a(n-1) + 2*a(n-2) - n|   (n ≥ 2).
 * a(1) is the first even term in this sequence. */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static state for memoisation of even terms */
    static seq_t *even_vals = NULL;   /* array of even terms */
    static size_t   cap     = 0;      /* current allocation capacity   */
    static size_t   len     = 0;      /* number of evens stored         */
    static idx_t   next_idx = 2;      /* next index k to compute (a_k) */
    static seq_t   prevprev = 1;      /* a_{k-2}  (a_0 for k=2)       */
    static seq_t   prev     = 1;      /* a_{k-1}  (a_1 for k=2)       */

    if (n == 0)   /* offset is 1, reject 0 explicitly */
        return 0;

    /* Grow storage and compute terms until we have at least n evens */
    if (len < (size_t)n) {
        /* Ensure enough capacity for the array of evens */
        while (cap < (size_t)n) {
            size_t new_cap = (cap == 0) ? 16 : cap * 2;
            seq_t *tmp = (seq_t *)realloc(even_vals, new_cap * sizeof(seq_t));
            if (!tmp)                /* allocation failure: return 0 */
                return 0;
            even_vals = tmp;
            cap = new_cap;
        }

        /* Generate terms of the base recurrence until we have n evens */
        while (len < (size_t)n) {
            /* Compute a_next = |prev + 2*prevprev - next_idx|   */
            seq_t sum = prev + (seq_t)2 * prevprev;   /* unsigned arithmetic */
            seq_t val;
            if (sum >= (seq_t)next_idx)
                val = sum - (seq_t)next_idx;
            else
                val = (seq_t)next_idx - sum;

            /* Record even values only */
            if ((val & 1) == 0)
                even_vals[len++] = val;

            /* Advance the recurrence state */
            prevprev = prev;
            prev     = val;
            ++next_idx;
        }
    }

    return even_vals[n - 1];  /* array is 0‑based, n is 1‑based */
}
